const API=window.__HATCHABLE__?.api||"/api",$=s=>document.querySelector(s);
const S={view:"explorer",patients:[],selected:null,sources:[],overview:null,member:null,workspaces:[],workspaceId:null,headers:[],rows:[],file:null,selectedSource:null,externalMode:true,hospitals:[],demoMode:false,workspaceReady:false,demoOps:null,demoAudit:[],dashboardFilter:{patient:[],diagnosis:[],medication:[],age:[],sex:[],source:[],signal:[]},dashboardData:null};
const esc=v=>String(v??"").replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]});
const titles={home:"Command Center",patients:"Patients",dashboard:"Dashboard",network:"PHC Network",resources:"Resources",actions:"Actions",explorer:"Hospital & Data Explorer",ai:"Connect with AI",data:"Data & Trust",help:"Help & Feedback"};
function toast(a,b){var x=document.createElement("div");x.className="toast";x.innerHTML="<b>"+esc(a)+"</b>"+(b?"<small>"+esc(b)+"</small>":"");document.body.appendChild(x);setTimeout(function(){x.remove()},3000)}
async function api(p,o){var headers=Object.assign({"Content-Type":"application/json"},(o&&o.headers)||{});if(S.workspaceId)headers["X-Workspace-Id"]=S.workspaceId;var r=await fetch(API+p,Object.assign({cache:"no-store"},o||{},{headers:headers}));var d={};try{d=await r.json()}catch(e){}if(!r.ok)throw Error(d.error||"Request failed");return d}
function section(h,p){return "<div class='section-title'><div><p class='eyebrow'>CARE & CTRL</p><h1>"+h+"</h1><p>"+p+"</p></div></div>"}
function help(a,b){return "<div class='helper'><b>What this does:</b> "+a+"<br><b>What you'll get:</b> "+b+"</div>"}
function metric(a,b,c){return "<article class='metric'><div class='label'>"+a+" <span>•</span></div><span class='value'>"+esc(b)+"</span><small>"+c+"</small></article>"}
function home(){if(S.externalMode){var c=liveCounts(),demo=S.demoMode;return "<div class=\"hero\"><div><p class=\"eyebrow\">COMMAND CENTER · "+(demo?"SYNTHETIC TEST WALKTHROUGH":"LIVE SOURCE")+"</p><h1>See earlier.<br><em>Decide smarter.</em></h1><p class=\"hero-copy\">Your selected healthcare dataset is now the source of truth. "+(demo?"Explore the complete synthetic patient-to-population-to-operations workflow without mixing it with real hospital records.":"Watch the live clinical picture change without mixing in unrelated records.")+"</p></div><div class=\"hero-state\"><div class=\"state-orb\"><i></i></div><div><small>ACTIVE DATA SOURCE</small><b>"+(demo?"SYNTHETIC TEST":"LIVE FHIR")+"</b><span>"+esc(S.selectedSource?.freshness||"Live connection")+"</span></div></div></div>"+liveSourceBadge()+"<div class=\"metrics\">"+metric("Patients",c.patients,"Current source records")+metric("Observations",c.signals,"Clinical measurements")+metric("Conditions",c.conditions,"Clinical context")+metric("Encounters",c.encounters,"Healthcare interactions")+"</div><div class=\"dashboard-grid\"><article class=\"panel signal-dashboard\"><div class=\"panel-head\"><div><p class=\"eyebrow\">LIVE SIGNAL PULSE</p><h2>Clinical activity at a glance</h2><p class=\"panel-copy\">A visual pulse of how much observation data is attached to each returned patient.</p></div><span class=\"badge\">LIVE</span></div><div class=\"pulse-bars\">"+S.patients.slice(0,12).map(function(p,i){var n=Number(p.signal_count||0),h=Math.max(10,Math.min(100,10+n*3));return "<div class=\"pulse-col\"><span style=\"height:"+h+"%\"></span><small>"+String(i+1).padStart(2,"0")+"</small></div>"}).join("")+"</div><div class=\"dashboard-legend\"><span><i></i> Observation volume</span><span>Source: "+esc(S.selectedSource?.endpoint||"FHIR")+"</span></div></article><article class=\"panel\"><div class=\"panel-head\"><div><p class=\"eyebrow\">SOURCE HEALTH</p><h2>Connection status</h2></div><span class=\"source-badge live\">CONNECTED</span></div><div class=\"health-stack\"><div><span>Patient records</span><b>"+c.patients+"</b></div><div><span>Clinical observations</span><b>"+c.signals+"</b></div><div><span>Last refresh</span><b>"+esc(S.selectedSource?.freshness||"—")+"</b></div></div><button class=\"button\" data-view=\"data\">Inspect provenance</button></article></div><div class=\"panel\"><div class=\"panel-head\"><div><p class=\"eyebrow\">CONNECTED LOOP</p><h2>From source → insight → action</h2><p class=\"panel-copy\">Operational action remains gated until the corresponding operational source is connected.</p></div><span class=\"badge\">HUMAN IN CONTROL</span></div><div class=\"journey\"><button class=\"journey-step\" data-view=\"patients\"><div class=\"journey-dot\">01</div><b>Patient</b><span>What changed?</span></button><button class=\"journey-step\" data-view=\"dashboard\"><div class=\"journey-dot\">02</div><b>Population</b><span>What is changing?</span></button><button class=\"journey-step\" data-view=\"network\"><div class=\"journey-dot\">03</div><b>Operations</b><span>What data is missing?</span></button><button class=\"journey-step\" data-view=\"actions\"><div class=\"journey-dot\">04</div><b>Action</b><span>What can we safely do?</span></button></div></div></div><!-- floating Copilot handles this globally --></div>"}+[["01","Patient","What changed?","patients"],["02","Population","What is changing?","dashboard"],["03","PHC pressure","Where is it building?","network"],["04","Resources","What will be needed?","resources"],["05","Action","What can we do?","actions"]];return "<div class='hero'><div><p class='eyebrow'>COMMAND CENTER · "+new Date().toLocaleDateString("en-IN")+"</p><h1>See earlier.<br><em>Decide smarter.</em></h1><p class='hero-copy'>CARE & CTRL connects changing patient signals to population patterns, facility pressure, resource needs and human-approved action — in one traceable workspace.</p></div><div class='hero-state'><div class='state-orb'><i></i></div><div><small>WORKSPACE STATE</small><b>"+(o.connected_sources?"Verified data connected":"Ready for your data")+"</b><span>Nothing is called live without a verified source.</span></div></div></div><div class='metrics'>"+metric("Patients needing attention",o.patients_needing_attention??"—","Verified signals")+metric("Active patients",o.active_patients??"—","Workspace records")+metric("Connected sources",o.connected_sources??"—","Verified connections")+metric("Human decisions pending",o.pending_human_decisions??"—","Awaiting review")+"</div><div class='workspace'><div><article class='panel'><div class='panel-head'><div><p class='eyebrow'>THE CONNECTED LOOP</p><h2>One story, from signal to action</h2><p class='panel-copy'>Every stage answers the next question. Click any stage.</p></div><span class='badge'>HUMAN IN CONTROL</span></div><div class='journey'>"+steps.map(function(s){return "<button class='journey-step' data-view='"+s[3]+"'><div class='journey-dot'>"+s[0]+"</div><b>"+s[1]+"</b><span>"+s[2]+"</span></button>"}).join("")+"</div></article><article class='panel'><div class='panel-head'><div><p class='eyebrow'>TRUST LAYER</p><h2>Evidence travels with every decision</h2></div><button class='button' data-view='data'>Review trust</button></div><div class='trust-row'><div class='trust-item'><b>Source</b><span>Where it came from.</span></div><div class='trust-item'><b>Freshness</b><span>When it was verified.</span></div><div class='trust-item'><b>Model</b><span>What produced the prediction.</span></div><div class='trust-item'><b>Approval</b><span>A person stays responsible.</span></div></div></article></div><article class='panel evidence-sentinel'><div class='panel-head'><div><p class='eyebrow'>EVIDENCE SENTINEL</p><h2>Know what the system actually knows</h2><p class='panel-copy'>A live integrity layer that separates connected evidence from unavailable or authorisation-gated data.</p></div><span class='badge'>TRACEABLE</span></div><div class='evidence-grid'><div><span>Source</span><b>"+esc(S.selectedSource?.type||"UNKNOWN")+"</b></div><div><span>Freshness</span><b>"+esc(S.selectedSource?.freshness||"Not available")+"</b></div><div><span>Clinical resources</span><b>"+Object.keys(S.selectedSource?.resource_counts||{}).length+"</b></div><div><span>Unavailable</span><b>"+(S.selectedSource?.unavailable_resources?.length||0)+"</b></div></div></article><!-- floating Copilot handles this globally --></div>"}
function patientRows(a){if(!a.length)return "<div class='empty'><div class='empty-icon'>◉</div><h2>No patients yet</h2><p>Connect a verified patient source or start the synthetic test walkthrough from Explorer.</p></div>";return a.map(function(p){var dx=p.diagnoses||p.conditions||[],md=p.medications||[];return "<button class='patient-row' data-patient='"+p.id+"'><div><b>"+esc(p.display_name)+"</b><small>"+esc(p.external_ref)+" · "+esc(p.sex||"Not specified")+" · "+esc(p.date_of_birth||"DOB unavailable")+"</small></div><div class='patient-meta'><b>"+esc(p.signal_count||0)+" signals</b><small>"+dx.length+" diagnoses · "+md.length+" medications</small></div></button>"}).join("")}
async function patientDetail(id){if(S.externalMode){var p=S.patients.find(function(x){return String(x.id)===String(id)});if(!p)return "<p>Patient not found.</p>";var dx=p.diagnoses||p.conditions||[],md=p.medications||[],sg=p.signals||p.latest_signals||[];return "<p class='eyebrow'>PATIENT DIGITAL TWIN · "+esc(p.dataType||"SOURCE DATA")+"</p><div class='patient-detail-head'><div><h2>"+esc(p.display_name)+"</h2><div class='detail-sub'>"+esc(p.external_ref)+" · "+esc(p.sex||"Not specified")+" · "+esc(p.date_of_birth||"DOB unavailable")+"</div></div><span class='source-badge sim'>"+esc(p.status||"active")+"</span></div><div class='helper' style='margin-top:14px'><b>Source:</b> "+esc(p.source||S.selectedSource?.name||"Connected source")+"<br><b>Data state:</b> "+esc(p.dataType||"Source-provided")+"</div><div class='patient-clinical-grid'><article class='panel'><p class='eyebrow'>DIAGNOSES · "+dx.length+"</p>"+(dx.length?dx.map(function(x){return "<div class='data-line'><span>"+esc(x.name||x.diagnosis_name||x)+"</span><b>Recorded</b></div>"}).join(""):"<p class='detail-sub'>No diagnosis records.</p>")+"</article><article class='panel'><p class='eyebrow'>MEDICATIONS · "+md.length+"</p>"+(md.length?md.map(function(x){return "<div class='data-line'><span>"+esc(x.name||x.medication_name||x)+"</span><b>"+esc(x.status||"Recorded")+"</b></div>"}).join(""):"<p class='detail-sub'>No medication records.</p>")+"</article></div><article class='panel'><div class='panel-head'><div><p class='eyebrow'>RECENT SIGNALS · "+sg.length+"</p><h3>Clinical timeline</h3></div><span class='badge'>SOURCE-BOUND</span></div>"+(sg.length?sg.slice(0,10).map(function(x){return "<div class='signal'><span>"+esc(x.signal_type||x.type||"Signal")+" · "+esc(x.unit||"")+"</span><b>"+esc(x.value_numeric??"—")+" <small>"+new Date(x.observed_at).toLocaleString("en-IN")+"</small></b></div>"}).join(""):"<p class='detail-sub'>No signal records.</p>")+"</article><div class='toolbar'><button class='button' data-view='explorer'>Change source</button><button class='button primary' data-focus-patient='"+id+"'>View in Dashboard →</button></div>";}var d=await api("/patients/"+id),s=d.signals||[];return "<p class='eyebrow'>PATIENT DIGITAL TWIN</p><h2>"+esc(d.patient.display_name)+"</h2><div class='detail-sub'>"+esc(d.patient.external_ref)+" · "+esc(d.patient.status)+"</div><div class='toolbar'><button class='button primary' data-signal='"+id+"'>+ Add signal</button></div>"+(s.length?s.slice(0,15).map(function(x){return "<div class='signal'><span>"+esc(x.signal_type)+" "+esc(x.unit||"")+"</span><b>"+esc(x.value_numeric)+" <small>"+new Date(x.observed_at).toLocaleString("en-IN")+"</small></b></div>"}).join(""):"<p class='detail-sub'>No signals yet. Add one to start the timeline.</p>")}
async function patients(){
 if(!S.externalMode){var d=await api("/patients/list");S.patients=d.rows||[]}
 var pCount=S.patients.length,signalCount=S.patients.reduce(function(a,p){return a+Number(p.signal_count||0)},0);
 return section("Patients","Inspect one person, then widen the lens to the population without leaving the patient workspace.")
 +liveSourceBadge()
 +"<div class='patient-population-strip'><div><p class='eyebrow'>PATIENT → POPULATION</p><h2>From one patient to the wider cohort</h2><p>Select a patient for a focused Digital Twin, or open the population controls below to compare diagnosis, medication, age, sex and signal patterns.</p></div><div class='patient-population-stats'><span><b>"+pCount+"</b><small>patients</small></span><span><b>"+signalCount+"</b><small>signals</small></span></div></div>"
 +"<div class='toolbar patient-toolbar'><input class='input' id='patientSearch' placeholder='Search patient or reference…'>"+(S.externalMode?"<span class='source-badge sim'>SOURCE-DRIVEN PATIENTS</span>":"<button class='button primary' id='addPatient'>+ Register patient</button>")+"<button class='button dark' id='openPopulationControls'>Population view →</button></div>"
 +"<div class='patient-grid'><div class='patient-list' id='patientList'>"+patientRows(S.patients)+"</div><div class='detail' id='patientDetail'>"+(S.selected?await patientDetail(S.selected):"<div class='empty'><div class='empty-icon'>◉</div><h2>Select a patient</h2><p>Choose a patient to inspect its Digital Twin.</p></div>")+"</div></div>"
 +"<div class='patient-population-section' id='patientPopulationSection'><div class='section-divider'><span>POPULATION INSIGHT</span></div><div class='population-control-head'><div><p class='eyebrow'>FILTER THE PATIENT COHORT</p><h2>Who are we looking at?</h2><p>These controls affect the cohort view in Dashboard and never change the underlying source records.</p></div><button class='button' id='sendFilteredToDashboard'>Open filtered Dashboard →</button></div><div class='filter-grid compact-filter-grid'><label><span>PATIENT</span><select id='patientPopPatient'><option value=''>All patients</option></select></label><label><span>DIAGNOSIS</span><select id='patientPopDiagnosis'><option value=''>All diagnoses</option></select></label><label><span>MEDICATION</span><select id='patientPopMedication'><option value=''>All medications</option></select></label><label><span>AGE GROUP</span><select id='patientPopAge'><option value=''>All ages</option><option>0–17</option><option>18–29</option><option>30–44</option><option>45–59</option><option>60–74</option><option>75+</option></select></label><label><span>SEX</span><select id='patientPopSex'><option value=''>All</option><option>female</option><option>male</option><option>other</option><option>unknown</option></select></label><label><span>SIGNAL</span><select id='patientPopSignal'><option value=''>All signals</option></select></label></div><div class='filter-summary' id='patientPopSummary'>Use the filters, then open Dashboard to see the selected cohort.</div></div>"
}
function population(){var n=S.patients.length,s=S.patients.reduce(function(a,p){return a+Number(p.signal_count||0)},0);return section("Population Intelligence","Move from individual changes to local patterns without losing source and freshness.")+help("Aggregates records currently available in your workspace.","Cohort size, signal volume and explicit evidence state.")+"<div class='cards'><div class='info-card'><p class='eyebrow'>COHORT</p><h3>Patients</h3><div class='big-number'>"+n+"</div><p>Current records.</p></div><div class='info-card'><p class='eyebrow'>SIGNALS</p><h3>Recorded signals</h3><div class='big-number'>"+s+"</div><p>Timestamped patient signals.</p></div><div class='info-card'><p class='eyebrow'>EVIDENCE</p><h3>State</h3><div class='big-number' style='font-size:20px'>Source-bound</div><p>No trend is invented without enough evidence.</p></div></div>"}
async function network(){var r=S.demoMode&&S.demoOps?S.demoOps.facilities:((await api("/phc/network")).facilities||[]);var demo=S.demoMode?"<div class=\"demo-banner\"><b>SIMULATED SCENARIO</b> · Facility capacity and pressure are synthetic operational records for the walkthrough.</div>":"";return section("PHC Network","See where facility pressure is building and where operational coverage exists.")+demo+help("Maps connected facilities, capacity and resource-record coverage.","A facility-level view that feeds the resource and action layers.")+"<div class=\"cards\">"+metric("Facilities",r.length,"Connected in this scenario")+metric("Under pressure",r.filter(function(x){return /pressure/i.test(x.status)}).length,"Requires review")+metric("Total capacity",r.reduce(function(a,x){return a+Number(x.capacity_total||0)},0),"Simulated places")+"</div><div class=\"table-wrap\"><table><thead><tr><th>Facility</th><th>District</th><th>Status</th><th>Capacity</th><th>Resources</th></tr></thead><tbody>"+(r.length?r.map(function(x){return "<tr><td><b>"+esc(x.name)+"</b><small>"+esc(x.external_ref||"")+"</small></td><td>"+esc(x.district||"—")+"</td><td><span class=\"status\">"+esc(x.status)+"</span></td><td>"+esc(x.capacity_total??"—")+"</td><td>"+esc(x.resource_records||0)+"</td></tr>"}).join(""):"<tr><td colspan=\"5\">No verified facilities connected yet.</td></tr>")+"</tbody></table></div>"}
async function resources(){var r=S.demoMode&&S.demoOps?S.demoOps.resources:((await api("/resources/forecast")).rows||[]);var demo=S.demoMode?"<div class=\"demo-banner\"><b>SIMULATED SCENARIO</b> · Inventory, usage and reorder thresholds are synthetic. The calculation itself is the same resource-forecast logic.</div>":"";return section("Resource Forecast","Translate operational pressure into transparent forward resource requirements.")+demo+help("Calculates days-to-reorder from observed stock, usage and thresholds.","Every row shows the numbers behind the forecast, not a black-box label.")+"<div class=\"cards\">"+metric("Resource records",r.length,"Across simulated facilities")+metric("Below reorder",r.filter(function(x){return Number(x.quantity_available)<=Number(x.reorder_level)}).length,"Needs attention")+metric("Urgent < 3 days",r.filter(function(x){return x.days_to_reorder!=null&&Number(x.days_to_reorder)<3}).length,"Priority queue")+"</div><div class=\"table-wrap\"><table><thead><tr><th>Resource</th><th>Facility</th><th>Available</th><th>Daily use</th><th>Reorder</th><th>Headroom</th></tr></thead><tbody>"+(r.length?r.map(function(x){var d=x.days_to_reorder==null?null:Number(x.days_to_reorder);return "<tr><td><b>"+esc(x.resource_name)+"</b><small>"+esc(x.unit)+"</small></td><td>"+esc(x.facility_name)+"</td><td>"+esc(x.quantity_available)+"</td><td>"+esc(x.average_daily_use)+"/day</td><td>"+esc(x.reorder_level)+"</td><td><span class=\"status\">"+(d==null?"Insufficient data":d.toFixed(1)+" days")+"</span></td></tr>"}).join(""):"<tr><td colspan=\"6\">No resource inventory connected yet.</td></tr>")+"</tbody></table></div>"}
async function actions(){var r=S.demoMode&&S.demoOps?S.demoOps.actions:((await api("/actions/list")).rows||[]);var demo=S.demoMode?"<div class=\"demo-banner\"><b>SIMULATED DECISION QUEUE</b> · Recommendations are synthetic and exist only to demonstrate human approval, rejection and audit behaviour.</div>":"";return section("Action Center","Review evidence, simulate consequences, and keep a human responsible for the final decision.")+demo+help("Holds recommendations until a responsible person reviews the rationale and expected impact.","A visible human-in-the-loop decision layer.")+"<div class=\"toolbar\"><button class=\"button dark\" id=\"simulatorBtn\">Open what-if simulator</button></div><div class=\"cards\">"+(r.length?r.map(function(x){return "<article class=\"info-card demo-action-card\" data-demo-action-card=\""+esc(x.id)+"\"><span class=\"status\">"+esc(x.status)+"</span><p class=\"eyebrow\">"+esc(x.target_type||"decision")+"</p><h3>"+esc(x.action_type)+"</h3><p><b>Why:</b> "+esc(x.rationale)+"</p><p><b>Expected:</b> "+esc(x.expected_impact||"Not specified")+"</p>"+(x.status==="pending"?"<div class=\"modal-actions\"><button class=\"button\" data-demo-action=\""+x.id+"\" data-demo-status=\"rejected\">Reject</button><button class=\"button primary\" data-demo-action=\""+x.id+"\" data-demo-status=\"approved\">Approve</button></div>":"<small>Decision recorded in this demo session.</small>")+"</article>"}).join(""):"<article class=\"info-card\"><h3>No pending recommendations</h3><p>Verified recommendations will appear here for human review.</p></article>")+"</div>"}
function facilityConnection(endpoint){if(!S.selectedSource||!S.selectedSource.facility)return '';var h=S.selectedSource.facility;var live=endpoint?.liveEndpoint;var liveBlock=live?"<div class='connection-option'><span class='badge'>PUBLIC FHIR DISCOVERY</span><h3>Live patient endpoint found</h3><p>CARE & CTRL found a FHIR endpoint associated with this facility. It will test the endpoint and use its Patient + available clinical resources as the workspace source of truth if access is permitted.</p><button class='button primary' data-live-endpoint='"+esc(live.endpoint)+"'>Load live patient data</button><a class='button' target='_blank' rel='noopener' href='"+esc(live.endpoint)+"'>Open FHIR endpoint ↗</a></div>":"<div class='connection-option'><span class='badge'>PUBLIC FHIR DISCOVERY</span><h3>No public endpoint found</h3><p>No matching public patient endpoint was discovered in the checked directories. The hospital may still have a private or authorised API.</p><span class='source-badge'>DIRECTORY CHECKED</span></div>";return "<article class='explore-card facility-connection' id='facilityConnection'><p class='eyebrow'>SELECTED FACILITY · DATA CONNECTION</p><h2>"+esc(h.name)+"</h2><p>We found the facility in the public directory. The directory does <b>not</b> expose its private patient database. Choose an authorised patient feed or import an authorised hospital export to continue.</p><div class='connection-grid'>"+liveBlock+"<div class='connection-option'><span class='badge'>FACILITY</span><h3>Facility context</h3><p>Location, identity and public directory information are connected now.</p><button class='button' disabled>Connected</button></div><div class='connection-option'><span class='badge'>PATIENT DATA</span><h3>Fallback: synthetic test feed</h3><p>Use this only when an authorised hospital source is unavailable. These records are synthetic/test data and are <b>not</b> patients of the selected hospital.</p><button class='button' data-connect-source='hapi-r4'>Use synthetic demo</button></div><div class='connection-option'><span class='badge'>YOUR DATA</span><h3>Authorised hospital CSV</h3><p>Upload an approved export from this facility and CARE & CTRL will validate, map and import it.</p><button class='button' data-scroll-csv>Upload CSV</button></div><div class='connection-option'><span class='badge'>AUTHORISED FHIR</span><h3>Connect an endpoint</h3><p>If this hospital uses a protected FHIR server, paste its authorised R4 base URL and CARE & CTRL will test it before loading any patient data.</p><input class='input' id='manualFhirEndpoint' placeholder='https://hospital.example/fhir/R4' style='width:100%;margin:8px 0'><button class='button primary' id='manualFhirBtn'>Test & connect</button></div></div></article>"}
async function explorer(){var d=await api("/explorer/sources");S.sources=d.sources||[];var endpoint=S.selectedSource?.endpointDiscovery||null;if(S.selectedSource?.facility&&!endpoint&&!S.selectedSource?.endpointDiscoveryChecked){S.selectedSource.endpointDiscoveryChecked=true;try{endpoint=await api("/explorer/endpoint-match?name="+encodeURIComponent(S.selectedSource.facility.name)+"&city="+encodeURIComponent(S.selectedSource.facility.city||"")+"&country="+encodeURIComponent(S.selectedSource.facility.country||""));S.selectedSource.endpointDiscovery=endpoint}catch(e){endpoint={liveEndpoint:null,note:"Endpoint discovery temporarily unavailable."};S.selectedSource.endpointDiscovery=endpoint}}return section("Hospital & Data Explorer","Choose exactly one source of truth for this CARE & CTRL workspace.")+"<div class=\"source-choice\"><article class=\"choice-card\"><div class=\"choice-kicker\"><span class=\"choice-icon\">⌁</span><span class=\"source-badge live\">OPTION 01 · LIVE</span></div><h3>Connect a live healthcare source</h3><p>Find a hospital worldwide, discover an accessible FHIR endpoint, and let its current Patient + clinical resources drive the workspace.</p><button class=\"button primary\" data-scroll-hospitals>Find a hospital</button></article><article class=\"choice-card\"><div class=\"choice-kicker\"><span class=\"choice-icon\">↥</span><span class=\"source-badge\">OPTION 02 · IMPORT</span></div><h3>Upload a healthcare database</h3><p>Import an authorised CSV, map the columns, validate it, and make the imported snapshot the workspace source of truth.</p><button class=\"button\" data-scroll-csv>Upload healthcare CSV</button></article></div>"+liveSourceBadge()+facilityConnection(endpoint)+help("Start with either a live connected source or an authorised healthcare database upload. The active source controls the downstream patient and population views.","A visible source state, freshness, provenance and a traceable path from data to decision.")+"<article class='source-hub'><div class='hub-top'><div><p class='eyebrow'>START HERE · FACILITY DISCOVERY</p><h2>Where should CARE & CTRL look?</h2><p>Search worldwide by city, state, country or hospital name. Or use your location to find nearby facilities.</p></div><button class='button primary' id='nearMe'>◎ Hospitals near me</button></div><div class='location-search'><input class='input' id='locationQuery' placeholder='Try: Chennai, Madurai, Tamil Nadu, London, New York…'><button class='button dark' id='findHospitals'>Find hospitals</button></div><div id='hospitalResults' class='hospital-results'><div class='empty compact'><div class='empty-icon'>⌖</div><h2>Search a location to begin</h2><p>Hospital listings come from OpenStreetMap. They are facility data, not private patient records.</p></div></div></article><div id='facilityConnection'></div><div class='explorer explorer-lower'><article class='explore-card'><p class='eyebrow'>PATIENT-DATA SOURCES</p><h2>Use a connected data source</h2><p>These are the sources that can actually provide patient records to the workspace. Synthetic/test data is clearly labelled.</p><div class='source-list' id='sourceList'>"+sourceRows(S.sources)+"</div></article><article class='explore-card'><p class='eyebrow'>YOUR ORGANISATION</p><h2>Upload any healthcare file</h2><p>CSV, Excel, PDF, DOCX, JSON, text and image-based records are analysed automatically. CARE & CTRL identifies the structure, cleans obvious formatting noise, maps the content and routes it into the right healthcare layer.</p><div class='dropzone'><input id='csvFile' type='file' accept='.csv,.json,.txt,.pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,application/pdf,application/json,text/plain,image/*'><label for='csvFile'>Choose a healthcare file<br><span>Nothing is imported until CARE & CTRL analyses and you confirm.</span></label></div><div id='csvStatus'></div></article></div>"}
function sourceRows(r){return r.map(function(s){return "<div class='source-row'><div><b>"+esc(s.name)+"</b><small>"+esc(s.region)+" · "+esc(s.freshness)+"</small></div><div class='source-actions'><span class='source-badge'>"+esc(s.type)+"</span><button class='button' data-source='"+s.id+"'>View</button></div></div>"}).join("")}
async function reports(){var r=S.demoMode?S.demoAudit:((await api("/reports/summary")).events||[]);var actionCount=S.demoMode?(S.demoOps?.actions||[]).filter(function(x){return x.status!=="pending"}).length:0;return section("Reports","Trace what the system saw, recommended and what people decided.")+(S.demoMode?"<div class=\"demo-banner\"><b>SIMULATED AUDIT TRAIL</b> · This report records actions taken during the current judge session; nothing is written into a hospital workspace.</div>":"")+help("Turns system events into a traceable decision record.","Source events, action states, provenance and human decisions.")+"<div class=\"cards\"><div class=\"info-card\"><h3>Audit events</h3><div class=\"big-number\">"+r.length+"</div></div><div class=\"info-card\"><h3>Decisions recorded</h3><div class=\"big-number\">"+actionCount+"</div></div><div class=\"info-card\"><h3>Evidence mode</h3><div class=\"big-number\" style=\"font-size:20px\">"+(S.demoMode?"SIMULATED":"WORKSPACE")+"</div></div></div><div class=\"table-wrap\"><table><thead><tr><th>Event</th><th>Detail</th><th>Actor</th><th>Time</th></tr></thead><tbody>"+(r.length?r.slice(0,40).map(function(e){return "<tr><td><b>"+esc(e.event_type)+"</b></td><td>"+esc(e.detail||"—")+"</td><td>"+esc(e.actor_id||"—")+"</td><td>"+new Date(e.created_at).toLocaleString("en-IN")+"</td></tr>"}).join(""):"<tr><td colspan=\"4\">No audit events yet.</td></tr>")+"</tbody></table></div>"}
function dataView(){var o=S.overview||{};return section("Data & Trust","Know what is connected, what is fresh, what was imported, and what the system is allowed to claim.")+help("Makes provenance, freshness, authentication and human-control visible.","A trust layer distinguishing live, imported, research and simulated sources.")+"<div class='cards'><div class='info-card'><p class='eyebrow'>IDENTITY</p><h3>Workspace</h3><div class='big-number' style='font-size:20px'>"+esc(S.member?.display_name||"Authenticated")+"</div><p>"+esc(S.member?.role||"Workspace user")+"</p></div><div class='info-card'><p class='eyebrow'>SOURCES</p><h3>Connected</h3><div class='big-number'>"+esc(o.connected_sources??0)+"</div><p>Verified connected sources.</p></div><div class='info-card'><p class='eyebrow'>SAFETY</p><h3>Human approval</h3><div class='big-number' style='font-size:20px'>Required</div><p>Recommendations do not auto-approve.</p></div></div>"}
function liveSourceBadge(){if(!S.selectedSource)return "";var s=S.selectedSource;var live=s.type==="LIVE FHIR",sim=/SIMULATED|SYNTHETIC|TEST/i.test(s.type+" "+(s.dataType||""));var label=live?"LIVE FHIR":sim?"SYNTHETIC TEST":"IMPORTED SNAPSHOT";return "<div class='active-source'><span class='source-pulse "+(live?"live":"")+"' ></span><div><b>"+esc(label)+"</b><small>"+esc(s.name||s.endpoint||"Active healthcare dataset")+" · "+esc(s.freshness||"Source selected")+"</small></div><button class='button' data-view='explorer'>Change source</button></div>"}
function sourceBoundPage(title,desc,body){return section(title,desc)+liveSourceBadge()+body}
function liveCounts(){var p=S.patients||[],signals=p.reduce(function(a,x){return a+Number(x.signal_count||0)},0),conds=p.reduce(function(a,x){return a+(x.conditions||[]).length},0),enc=p.reduce(function(a,x){return a+(x.encounters||[]).length},0);return {patients:p.length,signals:signals,conditions:conds,encounters:enc}}
patientDetail=async function(id){if(!S.externalMode)return await patientDetailDb(id);var p=S.patients.find(function(x){return String(x.id)===String(id)});if(!p)return "<p>Patient not found.</p>";var sig=p.signals||p.latest_signals||[],conds=p.conditions||[],enc=p.encounters||[],meds=p.medications||[];var photo=p.photo_url?"<img class='patient-photo' src='"+esc(p.photo_url)+"' alt='Patient profile'>":"<div class='patient-photo placeholder'>"+esc((p.display_name||"P").slice(0,1).toUpperCase())+"</div>";return "<div class='patient360-head'>"+photo+"<div><p class='eyebrow'>CONNECTED PATIENT DIGITAL TWIN</p><h2>"+esc(p.display_name)+"</h2><div class='detail-sub'>"+esc(p.external_ref)+"</div><div class='profile-tags'><span>"+esc(p.sex||"Not specified")+"</span><span>"+esc(p.date_of_birth||"DOB unavailable")+"</span></div></div></div><div class='helper'><b>Source:</b> "+esc(p.source||S.selectedSource?.name||"Connected source")+"<br><b>Data state:</b> "+esc(p.dataType||"Source-provided")+"<br><b>Freshness:</b> "+esc(S.selectedSource?.freshness||"Live source")+"</div><div class='patient360-grid'><article class='panel'><p class='eyebrow'>OBSERVATIONS · "+sig.length+"</p><h3>Latest clinical signals</h3>"+(sig.length?sig.slice(0,20).map(function(x){return "<div class='signal'><span>"+esc(x.type||x.signal_type||"Observation")+" "+esc(x.unit||"")+"</span><b>"+esc(x.value??x.value_numeric??"—")+" <small>"+(x.observed_at?new Date(x.observed_at).toLocaleString("en-IN"):"Time unavailable")+"</small></b></div>"}).join(""):"<p class='detail-sub'>No observations were returned.</p>")+"</article><article class='panel'><p class='eyebrow'>DIAGNOSES · "+conds.length+"</p><h3>History</h3>"+(conds.length?conds.slice(0,12).map(function(x){return "<div class='data-line'><span>"+esc(x.name)+"</span><b>"+esc(x.clinical_status||"Recorded")+"</b></div>"}).join(""):"<p class='detail-sub'>No Condition resources returned.</p>")+"<p class='eyebrow' style='margin-top:18px'>MEDICATIONS · "+meds.length+"</p>"+(meds.length?meds.map(function(x){return "<div class='data-line'><span>"+esc(x.name)+"<small>"+esc(x.dose||"")+"</small></span><b>"+esc(x.frequency||x.status||"Recorded")+"</b></div>"}).join(""):"<p class='detail-sub'>No medication resources returned by this source.</p>")+"</article></div><article class='panel'><p class='eyebrow'>ENCOUNTERS · "+enc.length+"</p>"+(enc.length?enc.slice(0,10).map(function(x){return "<div class='data-line'><span>"+esc(x.type||"Encounter")+"</span><b>"+esc(x.status||"Recorded")+"</b></div>"}).join(""):"<p class='detail-sub'>No Encounter resources returned.</p>")+"</article><div class='toolbar'><button class='button' data-view='explorer'>Change source</button><button class='button primary' data-focus-patient='"+id+"'>View in Dashboard →</button></div>"}
async function patientDetailDb(id){
var d=await api("/patients/"+id),p=d.patient||{},s=d.signals||[],dx=d.diagnoses||[],m=d.medications||[],a=d.attributes||[],docs=d.documents||[];
var photo=p.photo_url?"<img class=\"patient-photo\" src=\""+esc(p.photo_url)+"\" alt=\"Patient profile\">":"<div class=\"patient-photo placeholder\">"+esc((p.display_name||"P").slice(0,1).toUpperCase())+"</div>";
return "<div class=\"patient360-head\">"+photo+"<div><p class=\"eyebrow\">PATIENT 360 · DIGITAL TWIN</p><h2>"+esc(p.display_name)+"</h2><div class=\"detail-sub\">"+esc(p.external_ref||"")+"</div><div class=\"profile-tags\"><span>"+esc(p.sex||"Sex not available")+"</span><span>"+esc(p.date_of_birth||"DOB not available")+"</span><span>"+esc(p.blood_group||"Blood group not available")+"</span></div></div></div>"
+"<div class=\"helper\"><b>Source-bound:</b> Only information actually available in the workspace is shown. <b>Last updated:</b> "+esc(p.updated_at||"—")+"</div>"
+"<div class=\"patient360-grid\"><article class=\"panel\"><p class=\"eyebrow\">CLINICAL TIMELINE · "+s.length+"</p><h3>Latest observations</h3>"+(s.length?s.slice(0,25).map(function(x){return "<div class=\"signal\"><span>"+esc(x.signal_type)+" "+esc(x.unit||"")+"</span><b>"+esc(x.value_numeric)+" <small>"+(x.observed_at?new Date(x.observed_at).toLocaleString("en-IN"):"Time unavailable")+"</small></b></div>"}).join(""):"<p class=\"detail-sub\">No observations available.</p>")+"</article>"
+"<article class=\"panel\"><p class=\"eyebrow\">DIAGNOSES · "+dx.length+"</p><h3>Clinical history</h3>"+(dx.length?dx.map(function(x){return "<div class=\"data-line\"><span>"+esc(x.diagnosis_name)+"</span><b>"+esc(x.clinical_status||"Recorded")+"</b></div>"}).join(""):"<p class=\"detail-sub\">No diagnosis records available.</p>")+"<p class=\"eyebrow\" style=\"margin-top:20px\">MEDICATIONS · "+m.length+"</p>"+(m.length?m.map(function(x){return "<div class=\"data-line\"><span>"+esc(x.medication_name)+"<small>"+esc(x.dose||"")+"</small></span><b>"+esc(x.frequency||x.status||"Recorded")+"</b></div>"}).join(""):"<p class=\"detail-sub\">No medication records available.</p>")+"</article></div>"
+"<article class=\"panel\"><div class=\"panel-head\"><div><p class=\"eyebrow\">ADDITIONAL RECORDS</p><h3>Attributes & documents</h3></div></div><div class=\"chip-cloud\">"+(a.length?a.slice(0,30).map(function(x){return "<span class=\"data-chip\"><b>"+esc(x.attribute_key)+"</b> · "+esc(x.attribute_value)+"</span>"}).join(""):"<span class=\"detail-sub\">No additional attributes.</span>")+"</div>"+(docs.length?"<div class=\"doc-list\">"+docs.map(function(x){return "<div class=\"data-line\"><span>"+esc(x.file_name)+"</span><b>"+esc(x.file_type||"document")+"</b></div>"}).join("")+"</div>":"")+"</article><div class=\"toolbar\"><button class=\"button\" data-view=\"patients\">Back to patients</button><button class=\"button primary\" data-focus-patient=\""+id+"\">View in Dashboard →</button></div>";
}
async function dashboard(){
 var d,idx,f=S.dashboardFilter||{};
 if(S.externalMode){
   idx=(S.patients||[]).map(function(p){return{id:p.id,display_name:p.display_name,external_ref:p.external_ref,date_of_birth:p.date_of_birth,sex:p.sex,status:p.status,diagnoses:(p.conditions||[]).map(function(x){return x.name||x}),medications:(p.medications||[]).map(function(x){return x.name||x}),signals:(p.signals||p.latest_signals||[]).map(function(x){return{type:x.type||x.signal_type||"",source_id:x.source_id||null}})}});
   d={patients:idx.length,patient_index:idx,diagnoses:[],medications:[]};
 }else{
   d=await api("/dashboard/insights");idx=d.patient_index||[];
 }
 S.dashboardData=d;
 var now=new Date();
 function ageGroup(x){if(!x)return"Unknown";var dt=new Date(x),age=now.getFullYear()-dt.getFullYear(),mm=now.getMonth()-dt.getMonth();if(mm<0||(mm===0&&now.getDate()<dt.getDate()))age--;if(age<18)return"0–17";if(age<30)return"18–29";if(age<45)return"30–44";if(age<60)return"45–59";if(age<75)return"60–74";return"75+"}
 function vals(k){var v=f[k];return Array.isArray(v)?v:(v?[v]:[])}
var fp=vals("patient"),fd=vals("diagnosis"),fm=vals("medication"),fa=vals("age"),fs=vals("sex"),fg=vals("signal"),fsource=vals("source");
var filtered=idx.filter(function(p){return(!fp.length||fp.includes(String(p.id)))&&(!fd.length||fd.some(function(x){return p.diagnoses.includes(x)}))&&(!fm.length||fm.some(function(x){return p.medications.includes(x)}))&&(!fa.length||fa.includes(ageGroup(p.date_of_birth)))&&(!fs.length||fs.includes(String(p.sex||"unknown").toLowerCase()))&&(!fg.length||fg.some(function(x){return p.signals.some(function(s){return String(s.type)===x})}))});
 var age={},diagnosis={},medication={},signal={};
 filtered.forEach(function(p){var a=ageGroup(p.date_of_birth);age[a]=(age[a]||0)+1;p.diagnoses.forEach(function(x){diagnosis[x]=(diagnosis[x]||0)+1});p.medications.forEach(function(x){medication[x]=(medication[x]||0)+1});p.signals.forEach(function(x){signal[x.type]=(signal[x.type]||0)+1})});
 var ageRows=Object.keys(age).map(function(k){return{label:k,count:age[k]}}),dxRows=Object.keys(diagnosis).map(function(k){return{name:k,count:diagnosis[k]}}).sort(function(a,b){return b.count-a.count}),medRows=Object.keys(medication).map(function(k){return{name:k,count:medication[k]}}).sort(function(a,b){return b.count-a.count}),sigRows=Object.keys(signal).map(function(k){return{name:k,count:signal[k]}}).sort(function(a,b){return b.count-a.count});
 var allDx=[...new Set(idx.flatMap(function(p){return p.diagnoses}))].sort(),allMed=[...new Set(idx.flatMap(function(p){return p.medications}))].sort(),allSig=[...new Set(idx.flatMap(function(p){return p.signals.map(function(s){return s.type})}))].sort();
 function opts(a,current){var c=Array.isArray(current)?current:(current?[current]:[]);return a.map(function(x){return"<option value='"+esc(x)+"' "+(c.includes(String(x))?"selected":"")+">"+esc(x)+"</option>"}).join("")}
 var patientOptions=idx.map(function(p){return"<option value='"+esc(p.id)+"' "+(fp.includes(String(p.id))?"selected":"")+">"+esc(p.display_name)+" · "+esc(p.external_ref||"")+"</option>"}).join("");
 var active=Object.keys(f).reduce(function(n,k){return n+vals(k).length},0);
 function multiMenu(key,label,list,current,limit){var c=vals(key),items=list.slice(0,limit||80);return "<details class='filter-menu'><summary><span>"+label+"</span><b>"+(c.length?(c.length+" selected"):"All")+"</b></summary><div class='filter-menu-body'>"+items.map(function(x){var value=typeof x==="object"?x.value:x,text=typeof x==="object"?x.text:x;return "<label><input type='checkbox' data-filter-key='"+key+"' value='"+esc(value)+"' "+(c.includes(String(value))?"checked":"")+"><span>"+esc(text)+"</span></label>"}).join("")+(items.length===0?"<em class='filter-empty'>No connected options yet.</em>":"")+"</div></details>"}
 var patientList=idx.map(function(p){return{value:String(p.id),text:(p.display_name||"Patient")+" · "+(p.external_ref||"")}}),sexList=["female","male","other","unknown"],ageList=["0–17","18–29","30–44","45–59","60–74","75+"];
 return section("Dashboard","One place to understand the whole connected dataset, narrow the cohort, and generate a reusable report.")
 +liveSourceBadge()
 +"<div class='dashboard-control panel'><div class='panel-head'><div><p class='eyebrow'>COHORT FILTERS</p><h2>Choose what you want to see</h2><p class='panel-copy'>Select multiple values in any category. Categories work together to narrow the same cohort.</p></div><span class='badge'>"+(active?active+" SELECTION"+(active>1?"S":""):"ALL DATA")+"</span></div><div class='filter-menu-grid'>"+multiMenu("patient","Patient",patientList,f.patient,120)+multiMenu("diagnosis","Diagnosis",allDx,f.diagnosis,80)+multiMenu("medication","Medication",allMed,f.medication,80)+multiMenu("age","Age group",ageList,f.age,20)+multiMenu("sex","Sex",sexList,f.sex,20)+multiMenu("signal","Signal",allSig,f.signal,80)+multiMenu("source","Source",[{value:"active",text:"Active connected source"}],f.source,10)+"</div><div class='filter-actions'><button class='button primary' id='applyDashFilters'>Apply filters</button><button class='button' id='clearDashFilters'>Clear all</button><span class='filter-hint'>You can combine multiple selections.</span></div><div class='filter-summary'><b>"+filtered.length+"</b> patients in view · "+(filtered.length===idx.length?"Full workspace cohort":"Filtered cohort")+"</div></div>"
 +"<div class='cards'>"+metric("Patients in view",filtered.length,"Filtered cohort")+metric("Clinical signals",filtered.reduce(function(a,p){return a+p.signals.length},0),"Recorded signal links")+metric("Diagnoses",dxRows.length,"Within this cohort")+metric("Medications",medRows.length,"Recorded medication types")+"</div>"
 +"<div class='dashboard-grid'><article class='panel'><div class='panel-head'><div><p class='eyebrow'>AGE COHORTS</p><h2>Who is in this view?</h2></div><span class='badge'>SOURCE-BOUND</span></div><div class='risk-list'>"+(ageRows.length?ageRows.map(function(x){return"<div class='risk-row'><span>"+esc(x.label)+"</span><b>"+x.count+"</b><i><em style='width:"+Math.min(100,(x.count/Math.max(1,filtered.length))*100)+"%'></em></i></div>"}).join(""):"<p class='detail-sub'>No records match the selected filters.</p>")+"</div></article><article class='panel'><div class='panel-head'><div><p class='eyebrow'>TOP DIAGNOSES</p><h2>Conditions in this view</h2></div></div>"+(dxRows.length?dxRows.slice(0,10).map(function(x){return"<div class='data-line'><span>"+esc(x.name)+"</span><b>"+x.count+"</b></div>"}).join(""):"<p class='detail-sub'>No diagnosis records in this cohort.</p>")+"</article></div>"
 +"<div class='dashboard-grid'><article class='panel'><div class='panel-head'><div><p class='eyebrow'>MEDICATIONS</p><h2>Recorded medication patterns</h2><p class='panel-copy'>Frequency means recorded medication rows; it does not infer actual consumption.</p></div></div>"+(medRows.length?medRows.slice(0,12).map(function(x){return"<div class='data-line'><span>"+esc(x.name)+"</span><b>"+x.count+" records</b></div>"}).join(""):"<p class='detail-sub'>No medication records in this cohort.</p>")+"</article><article class='panel'><div class='panel-head'><div><p class='eyebrow'>SIGNALS</p><h2>What is changing?</h2></div></div>"+(sigRows.length?sigRows.slice(0,12).map(function(x){return"<div class='data-line'><span>"+esc(x.name)+"</span><b>"+x.count+" patients</b></div>"}).join(""):"<p class='detail-sub'>No signal types in this cohort.</p>")+"</article></div>"
 +"<article class='panel report-panel'><div class='panel-head'><div><p class='eyebrow'>REPORT</p><h2>Generate a reusable workspace report</h2><p class='panel-copy'>Create a point-in-time PDF containing the current filters, cohort metrics, diagnoses, medications, signals and audit context.</p></div><span class='badge'>DOWNLOADABLE</span></div><div class='report-actions'><button class='button primary' id='generateReport'>Generate report</button><button class='button' id='downloadReport' disabled>Download PDF</button><span id='reportStatus' class='report-status'>No report generated yet.</span></div></article>";
}
