population=function(){var c=liveCounts();if(S.demoMode&&S.demoOps){var rb=S.demoOps.population.risk_bands,sm=S.demoOps.population.signal_mix,tr=S.demoOps.population.trend;return section("Population Intelligence","Move from individual clinical resources to an explainable simulated population picture.")+"<div class='demo-banner'><b>SIMULATED CLINICAL SCENARIO</b> · Risk bands and trends are synthetic demonstration analytics, not clinical predictions for real patients.</div><div class='cards'>"+metric("Patients",c.patients,"Synthetic FHIR records")+metric("Observations",c.signals,"Joined clinical measurements")+metric("Conditions + encounters",c.conditions+c.encounters,"Clinical context")+"</div><div class='dashboard-grid'><article class='panel'><div class='panel-head'><div><p class='eyebrow'>RISK DISTRIBUTION</p><h2>Population attention bands</h2><p class='panel-copy'>A demonstration of how the system can group source-derived signals for review.</p></div><span class='badge'>SIMULATED</span></div><div class='risk-list'>"+Object.keys(rb).map(function(k){return "<div class='risk-row'><span>"+esc(k)+"</span><b>"+rb[k]+"</b><i><em style='width:"+rb[k]+"%'></em></i></div>"}).join("")+"</div></article><article class='panel'><div class='panel-head'><div><p class='eyebrow'>SIGNAL MIX</p><h2>What is changing?</h2></div></div><div class='risk-list'>"+sm.map(function(x){return "<div class='risk-row'><span>"+esc(x.label)+"</span><b>"+x.value+"%</b><i><em style='width:"+x.value+"%'></em></i></div>"}).join("")+"</div><div class='feed-line'><span>Trend window</span><b>"+tr[0].label+" → "+tr[tr.length-1].label+"</b></div></article></div>"}return sourceBoundPage("Population Intelligence","See the population pattern emerging from the currently active healthcare source.","<div class='cards'><div class='info-card'><p class='eyebrow'>COHORT</p><h3>Patients</h3><div class='big-number'>"+c.patients+"</div><p>Records returned by the active source.</p></div><div class='info-card'><p class='eyebrow'>OBSERVATIONS</p><h3>Clinical signals</h3><div class='big-number'>"+c.signals+"</div><p>FHIR Observation resources joined to patients.</p></div><div class='info-card'><p class='eyebrow'>CLINICAL CONTEXT</p><h3>Conditions + encounters</h3><div class='big-number'>"+(c.conditions+c.encounters)+"</div></div></div>")}
network=async function(){if(S.demoMode&&S.demoOps){var r=S.demoOps.facilities;return section("PHC Network","See where simulated facility pressure is building and how it feeds resource decisions.")+"<div class='demo-banner'><b>SIMULATED SCENARIO</b> · Facility capacity and pressure are synthetic demonstration data.</div><div class='cards'>"+metric("Facilities",r.length,"Scenario coverage")+metric("Under pressure",r.filter(function(x){return /pressure/i.test(x.status)}).length,"Needs review")+metric("Capacity",r.reduce(function(a,x){return a+Number(x.capacity_total||0)},0),"Simulated places")+"</div><div class='table-wrap'><table><thead><tr><th>Facility</th><th>District</th><th>Status</th><th>Capacity</th><th>Resources</th></tr></thead><tbody>"+r.map(function(x){return "<tr><td><b>"+esc(x.name)+"</b><small>"+esc(x.external_ref)+"</small></td><td>"+esc(x.district)+"</td><td><span class='status'>"+esc(x.status)+"</span></td><td>"+x.capacity_total+"</td><td>"+x.resource_records+"</td></tr>"}).join("")+"</tbody></table></div>"}if(S.externalMode)return sourceBoundPage("PHC Network","Facility operations require an operational source; the selected patient FHIR endpoint does not expose inventory or PHC capacity here.","<div class='empty'><div class='empty-icon'>⌁</div><h2>Operational source not connected</h2><p>The selected live FHIR source provides patient/clinical resources. CARE & CTRL will not invent PHC capacity or resource records from them.</p><button class='button primary' data-view='explorer'>Connect an operations source</button></div>");return await networkDb()}
