resources=async function(){if(S.demoMode&&S.demoOps){var r=S.demoOps.resources;return section("Resource Forecast","Translate simulated operational pressure into a transparent forward requirement.")+"<div class='demo-banner'><b>SIMULATED SCENARIO</b> · Inventory, usage and reorder thresholds are synthetic. The calculation is the same headroom logic used by the product.</div><div class='cards'>"+metric("Resource records",r.length,"Scenario coverage")+metric("Below reorder",r.filter(function(x){return x.quantity_available<=x.reorder_level}).length,"Needs attention")+metric("Urgent < 3 days",r.filter(function(x){return x.days_to_reorder<3}).length,"Priority queue")+"</div><div class='table-wrap'><table><thead><tr><th>Resource</th><th>Facility</th><th>Available</th><th>Daily use</th><th>Reorder</th><th>Headroom</th></tr></thead><tbody>"+r.map(function(x){return "<tr><td><b>"+esc(x.resource_name)+"</b><small>"+esc(x.unit)+"</small></td><td>"+esc(x.facility_name)+"</td><td>"+x.quantity_available+"</td><td>"+x.average_daily_use+"/day</td><td>"+x.reorder_level+"</td><td><span class='status'>"+Number(x.days_to_reorder).toFixed(1)+" days</span></td></tr>"}).join("")+"</tbody></table></div>"}if(S.externalMode)return sourceBoundPage("Resource Forecast","Resource forecasting needs an operational inventory source; it is never inferred from patient records.","<div class='empty'><div class='empty-icon'>◌</div><h2>Inventory source not connected</h2><p>No stock, consumption or reorder records were returned by the selected patient-data endpoint.</p><button class='button primary' data-view='explorer'>Connect operations data</button></div>");return await resourcesDb()}
async function resourcesDb(){var d=await api("/resources/forecast"),r=d.rows||[];return section("Resource Forecast","Translate operational pressure into a forward resource requirement.")+help("Calculates days-to-reorder from observed stock, usage and thresholds.","Transparent resource outlook; no forecast where underlying data is missing.")+"<div class='table-wrap'><table><thead><tr><th>Resource</th><th>Facility</th><th>Available</th><th>Daily use</th><th>Reorder</th><th>Days</th></tr></thead><tbody>"+(r.length?r.map(function(x){return "<tr><td><b>"+esc(x.resource_name)+"</b></td><td>"+esc(x.facility_name)+"</td><td>"+esc(x.quantity_available)+" "+esc(x.unit)+"</td><td>"+esc(x.average_daily_use)+"</td><td>"+esc(x.reorder_level)+"</td><td>"+(x.days_to_reorder==null?"Insufficient data":Number(x.days_to_reorder).toFixed(1)+" days")+"</td></tr>"}).join(""):"<tr><td colspan='6'>No resource inventory connected yet.</td></tr>")+"</tbody></table></div>"}
actions=async function(){if(S.demoMode&&S.demoOps){var r=S.demoOps.actions;return section("Action Center","Review evidence, simulate consequences, and keep a human responsible for the final decision.")+"<div class='demo-banner'><b>SIMULATED DECISION QUEUE</b> · Recommendations are synthetic. Approve or reject them to demonstrate the human-in-the-loop workflow.</div><div class='toolbar'><button class='button dark' id='simulatorBtn'>Open what-if simulator</button></div><div class='cards'>"+r.map(function(x){return "<article class='info-card demo-action-card'><span class='status'>"+esc(x.status)+"</span><p class='eyebrow'>"+esc(x.target_type)+"</p><h3>"+esc(x.action_type)+"</h3><p><b>Why:</b> "+esc(x.rationale)+"</p><p><b>Expected:</b> "+esc(x.expected_impact)+"</p>"+(x.status==="pending"?"<div class='modal-actions'><button class='button' data-demo-action='"+x.id+"' data-demo-status='rejected'>Reject</button><button class='button primary' data-demo-action='"+x.id+"' data-demo-status='approved'>Approve</button></div>":"<small>Decision recorded in this demo session.</small>")+"</article>"}).join("")+"</div>"}if(S.externalMode)return sourceBoundPage("Action Center","Live clinical data can inform evidence, but CARE & CTRL will not create operational actions without a connected operational source.","<div class='empty'><div class='empty-icon'>✓</div><h2>Human action layer is waiting for operational evidence</h2><p>The selected source contains patient clinical data. No unrelated action queue is shown as if it came from this hospital.</p><button class='button primary' data-view='explorer'>Connect operations data</button></div>");return await actionsDb()}
async function actionsDb(){var d=await api("/actions/list"),r=d.rows||[];return section("Action Center","Review evidence, simulate consequences, and keep a human responsible for the final decision.")+help("Holds recommendations until a responsible person reviews the rationale and expected impact.","Pending actions, explicit approval controls and an audit trail.")+"<div class='toolbar'><button class='button dark' id='simulatorBtn'>Open what-if simulator</button></div><div class='cards'>"+(r.length?r.map(function(x){return "<article class='info-card'><span class='status'>"+esc(x.status)+"</span><h3>"+esc(x.action_type)+"</h3><p><b>Why:</b> "+esc(x.rationale)+"</p><p><b>Expected:</b> "+esc(x.expected_impact||"Not specified")+"</p>"+(x.status==="pending"?"<div class='modal-actions'><button class='button' data-action='"+x.id+"' data-status='rejected'>Reject</button><button class='button primary' data-action='"+x.id+"' data-status='approved'>Approve</button></div>":"")+"</article>"}).join(""):"<article class='info-card'><h3>No pending recommendations</h3><p>Verified recommendations will appear here for human review.</p></article>")+"</div>"}
reports=async function(){if(S.demoMode&&S.demoOps){var r=S.demoAudit||[];var approved=(S.demoOps.actions||[]).filter(function(x){return x.status==="approved"}).length;var rejected=(S.demoOps.actions||[]).filter(function(x){return x.status==="rejected"}).length;return section("Reports","Trace the synthetic walkthrough from connected evidence to human decision.")+"<div class='demo-banner'><b>SIMULATED AUDIT TRAIL</b> · These events belong only to the current judge session and are not hospital records.</div><div class='cards'><div class='info-card'><h3>Audit events</h3><div class='big-number'>"+r.length+"</div></div><div class='info-card'><h3>Approved</h3><div class='big-number'>"+approved+"</div></div><div class='info-card'><h3>Rejected</h3><div class='big-number'>"+rejected+"</div></div></div><div class='table-wrap'><table><thead><tr><th>Event</th><th>Detail</th><th>Actor</th><th>Time</th></tr></thead><tbody>"+(r.length?r.map(function(x){return "<tr><td><b>"+esc(x.event_type)+"</b></td><td>"+esc(x.detail)+"</td><td>"+esc(x.actor_id)+"</td><td>"+new Date(x.created_at).toLocaleString("en-IN")+"</td></tr>"}).join(""):"<tr><td colspan='4'>No decisions recorded yet. Approve or reject an action to create one.</td></tr>")+"</tbody></table></div>"}return await reportsDb()}
async function reportsDb(){return await api("/reports/summary").then(function(d){var r=d.events||[];return section("Reports","Trace what the system saw, recommended and what people decided.")+"<div class='cards'><div class='info-card'><h3>Audit events</h3><div class='big-number'>"+r.length+"</div></div><div class='info-card'><h3>Actions</h3><div class='big-number'>"+(d.actions||[]).reduce(function(a,x){return a+Number(x.count||0)},0)+"</div></div><div class='info-card'><h3>Sources</h3><div class='big-number'>"+(d.sources||[]).length+"</div></div></div>"})}
