useLiveEndpoint=async function(endpoint){try{var d=await api('/explorer/fhir-live?endpoint='+encodeURIComponent(endpoint));S.selectedSource={...S.selectedSource,id:'live-fhir-'+Date.now(),type:'LIVE FHIR',freshness:'Live · fetched '+new Date(d.fetched_at).toLocaleTimeString('en-IN'),endpoint:d.source,description:'Current response from the selected public FHIR endpoint.',resource_counts:d.resource_counts,unavailable_resources:d.unavailable_resources};S.patients=d.patients||[];S.externalMode=true;S.view='patients';toast('LIVE FHIR connected',d.count+' patient records · '+d.resource_counts.Observation+' observations returned.');await render()}catch(e){toast('Live FHIR connection failed',e.message)}}
refreshExternalSource=async function(){if(!S.externalMode)return;var isLive=S.selectedSource?.type==="LIVE FHIR"||S.selectedSource?.type==="SIMULATED · FHIR",isHapi=S.selectedSource?.id==="hapi-r4"&&!isLive;if(!isLive&&!isHapi)return;try{var d=isLive?await api("/explorer/fhir-live?endpoint="+encodeURIComponent(S.selectedSource.endpoint)):await api("/explorer/fhir-patients?count=100");S.patients=d.patients||[];S.selectedSource.freshness=(isLive?"LIVE · ":"TEST · ")+new Date(d.fetched_at||Date.now()).toLocaleTimeString("en-IN");if(d.resource_counts)S.selectedSource.resource_counts=d.resource_counts;if(d.unavailable_resources)S.selectedSource.unavailable_resources=d.unavailable_resources;if(S.view==="patients"||S.view==="population"||S.view==="home")await render();$("#dataState").textContent="SOURCE LIVE · "+new Date(d.fetched_at||Date.now()).toLocaleTimeString("en-IN")}catch(e){S.selectedSource.stale=true;$("#dataState").textContent="SOURCE STALE · "+(S.selectedSource?.type||"DATA")}}

function aiWorkspace(){
  return section("Connect with AI","One conversational control layer for the entire CARE & CTRL workspace. Type or speak naturally; the AI stays grounded in your current evidence and can operate safe workspace controls.")
  +"<div class='ai-workspace-grid'><article class='ai-workspace-main'><div class='ai-work-head'><div><p class='eyebrow'>CARE & CTRL AI CONTROL</p><h2>Tell me what you need.</h2><p>Ask for data, results, dashboards, hospitals, uploads or navigation. I will use the current workspace context instead of making up a result.</p></div><span class='badge'>GROUNDED · HUMAN CONTROL</span></div>"
  +"<div class='ai-work-chat' id='aiWorkspaceChat'><div class='ai-work-msg ai'><span>CARE & CTRL AI</span><p>I'm connected to this workspace. Tell me what you want to see or do.</p><div class='ai-work-actions'>I can navigate, refresh, search facilities, open the upload flow, inspect available sources and explain connected data.</div></div></div>"
  +"<div class='ai-work-compose'><textarea id='aiWorkspaceInput' rows='3' placeholder='Example: “Find hospitals in Chennai and show me the available patient-data connections.”'></textarea><div class='ai-work-toolbar'><select id='aiWorkspaceLanguage' aria-label='AI language'><option value='auto'>Auto language</option><option value='English'>English</option><option value='தமிழ்'>தமிழ்</option><option value='हिन्दी'>हिन्दी</option><option value='తెలుగు'>తెలుగు</option><option value='ಕನ್ನಡ'>ಕನ್ನಡ</option><option value='മലയാളം'>മലയാളം</option><option value='বাংলা'>বাংলা</option><option value='मराठी'>मराठी</option><option value='ગુજરાતી'>ગુજરાતી</option></select><button class='ai-work-mic' id='aiWorkspaceMic' type='button'>🎙 Talk</button><button class='ai-work-send' id='aiWorkspaceSend' type='button'>Send →</button></div></div>"
  +"<div class='ai-work-suggestions'><button data-ai-prompt='Open the Dashboard'>Dashboard</button><button data-ai-prompt='Open Patients'>Patients</button><button data-ai-prompt='Find hospitals in Chennai'>Find hospitals</button><button data-ai-prompt='Open the healthcare file upload area'>Upload healthcare data</button><button data-ai-prompt='Refresh the connected source'>Refresh source</button></div></article>"
  +"<aside class='ai-work-sidebar'><div class='ai-capability'><span>01</span><div><b>Understand</b><p>Natural language, mixed language and source-aware questions.</p></div></div><div class='ai-capability'><span>02</span><div><b>Operate</b><p>Open views, refresh evidence, search facilities and start uploads.</p></div></div><div class='ai-capability'><span>03</span><div><b>Connect</b><p>Guide live FHIR, authorised hospital exports and workspace setup.</p></div></div><div class='ai-capability'><span>04</span><div><b>Explain</b><p>Results remain tied to source, freshness and available resources.</p></div></div><div class='ai-safety'><b>Human approval stays on</b><p>AI can prepare and navigate. It does not silently approve clinical or operational decisions.</p></div></aside></div>";
}
async function sendAiWorkspaceMessage(question){
  question=String(question||"").trim();if(!question)return;
  var input=$("#aiWorkspaceInput"),send=$("#aiWorkspaceSend"),chat=$("#aiWorkspaceChat"),lang=$("#aiWorkspaceLanguage")?.value||"auto";
  if(chat){var u=document.createElement("div");u.className="ai-work-msg user";u.innerHTML="<span>YOU</span><p>"+esc(question)+"</p>";chat.appendChild(u);chat.scrollTop=chat.scrollHeight}
  if(input)input.value="";if(send){send.disabled=true;send.textContent="Thinking…"}
  try{
    var ctx=copilotContext();ctx.preferred_language=lang;ctx.ai_workspace=true;ctx.available_sources=(S.sources||[]).map(function(s){return {id:s.id,name:s.name,type:s.type,region:s.region,patientFeed:s.patientFeed}});
    var out=await api("/copilot/ask",{method:"POST",body:JSON.stringify({question:question,context:ctx})});
    if(chat){
      var a=document.createElement("div");a.className="ai-work-msg ai";a.innerHTML="<span>CARE & CTRL AI</span><p>"+esc(out.answer||"No grounded answer was produced.")+"</p><div class='ai-work-actions'>"+(out.action&&out.action.type&&out.action.type!=="none"?"✓ "+esc(out.action.label||"Workspace action executed"):"Grounded in current workspace evidence")+"</div><button type='button' class='ai-listen' data-ai-speak='"+esc(out.answer||"")+"'>🔊 Listen</button>";chat.appendChild(a);chat.scrollTop=chat.scrollHeight
    }
    if(out.action&&out.action.type&&out.action.type!=="none")await executeCopilotAction(out.action);
  }catch(e){
    if(chat){var er=document.createElement("div");er.className="ai-work-msg ai error";er.innerHTML="<span>CARE & CTRL AI</span><p>"+esc(e.message||"AI service unavailable")+"</p>";chat.appendChild(er);chat.scrollTop=chat.scrollHeight}
  }finally{if(send){send.disabled=false;send.textContent="Send →"}}
}
function bindAiWorkspace(){
  var input=$("#aiWorkspaceInput"),send=$("#aiWorkspaceSend"),mic=$("#aiWorkspaceMic"),lang=$("#aiWorkspaceLanguage"),chat=$("#aiWorkspaceChat");
  if(!input)return;
  send.onclick=function(){sendAiWorkspaceMessage(input.value)};
  input.onkeydown=function(e){if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendAiWorkspaceMessage(input.value)}};
  document.querySelectorAll("[data-ai-prompt]").forEach(function(b){b.onclick=function(){sendAiWorkspaceMessage(b.dataset.aiPrompt)}});
  chat?.addEventListener("click",function(e){var b=e.target.closest("[data-ai-speak]");if(b&&"speechSynthesis" in window){var u=new SpeechSynthesisUtterance(b.dataset.aiSpeak);u.lang=(lang?.value&&lang.value!=="auto"?lang.value:"en-IN");window.speechSynthesis.cancel();window.speechSynthesis.speak(u)}});
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  var langs={auto:"en-IN","English":"en-IN","தமிழ்":"ta-IN","हिन्दी":"hi-IN","తెలుగు":"te-IN","ಕನ್ನಡ":"kn-IN","മലയാളം":"ml-IN","বাংলা":"bn-IN","मराठी":"mr-IN","ગુજરાતી":"gu-IN"};
  if(!SR){mic.disabled=true;mic.title="Voice input is not supported in this browser";return}
  var rec=new SR();rec.interimResults=true;rec.continuous=false;var listening=false;
  function setLang(){var v=lang.value;rec.lang=langs[v]||v||"en-IN"}
  lang.onchange=setLang;setLang();
  rec.onstart=function(){listening=true;mic.classList.add("listening");mic.textContent="■ Stop"};
  rec.onresult=function(e){var t="";for(var i=e.resultIndex;i<e.results.length;i++)t+=e.results[i][0].transcript;input.value=t};
  rec.onerror=function(){mic.classList.remove("listening");mic.textContent="🎙 Talk"};
  rec.onend=function(){listening=false;mic.classList.remove("listening");mic.textContent="🎙 Talk"};
  mic.onclick=function(){if(listening)rec.stop();else{setLang();try{rec.start()}catch(e){}}};
}
async function render(){document.querySelectorAll(".nav-item").forEach(function(b){b.classList.toggle("active",b.dataset.view===S.view)});$("#viewTitle").textContent=titles[S.view]||"CARE & CTRL";try{$("#app").innerHTML=S.view==="home"?home():S.view==="patients"?await patients():S.view==="dashboard"?await dashboard():S.view==="network"?await network():S.view==="resources"?await resources():S.view==="actions"?await actions():S.view==="explorer"?await explorer():S.view==="ai"?aiWorkspace():S.view==="help"?helpFeedback():dataView();bind();if(S.view==="ai")bindAiWorkspace()}catch(e){$("#app").innerHTML="<div class='empty'><div class='empty-icon'>!</div><h2>Could not load this workspace</h2><p>"+esc(e.message)+"</p><button class='button primary' data-retry>Retry</button></div>";bind()}}
async function findHospitals(q){q=String(q||"").trim();if(!q){toast("Choose a location","Enter a city, state or country.");return}$("#hospitalResults").innerHTML="<div class='loading-card'>Searching verified facility data…</div>";try{var d=await api("/explorer/hospitals?q="+encodeURIComponent(q));S.hospitals=d.hospitals||[];$("#hospitalResults").innerHTML=hospitalRows(S.hospitals,d);bind()}catch(e){$("#hospitalResults").innerHTML="<div class='empty'><div class='empty-icon'>!</div><h2>Hospital search unavailable</h2><p>"+esc(e.message)+"</p></div>"}} 
async function nearMe(){if(!navigator.geolocation){toast("Location unavailable","Enter your city instead.");return}$("#nearMe").disabled=true;navigator.geolocation.getCurrentPosition(async function(pos){try{var d=await api("/explorer/hospitals?lat="+pos.coords.latitude+"&lon="+pos.coords.longitude+"&radius=25000");S.hospitals=d.hospitals||[];$("#hospitalResults").innerHTML=hospitalRows(S.hospitals,d);bind()}catch(e){toast("Nearby search failed",e.message)}finally{$("#nearMe").disabled=false}},function(){toast("Location permission needed","Allow location access or search your city.");$("#nearMe").disabled=false},{enableHighAccuracy:true,timeout:10000,maximumAge:300000})}
function hospitalRows(rows,d){if(!rows.length)return "<div class='empty'><div class='empty-icon'>⌖</div><h2>No hospitals found</h2><p>Try a broader city/state/country search.</p></div>";return "<div class='results-head'><span>"+rows.length+" facilities found</span><small>"+esc(d.freshness||"Directory data")+" · "+esc(d.source||"Verified source")+"</small></div>"+rows.map(function(h){return "<article class='hospital-row'><div class='hospital-main'><div class='hospital-icon'>+</div><div><h3>"+esc(h.name)+"</h3><p>"+esc([h.city,h.state,h.country].filter(Boolean).join(" · ")||"Location available")+"</p><small>"+esc(h.patientData)+"</small></div></div><div class='hospital-actions'>"+(h.website?"<a class='button' target='_blank' rel='noopener' href='"+esc(h.website)+"'>Website ↗</a>":"")+"<button class='button primary' data-facility='"+esc(h.id)+"'>Use facility</button></div></article>"}).join("")}
async function useFacility(h){S.selectedSource={id:"facility-"+h.id,name:h.name,region:[h.city,h.state,h.country].filter(Boolean).join(", "),type:"FACILITY CONTEXT",freshness:"Community-updated",description:"Facility and location context from OpenStreetMap. This directory does not provide private patient records.",url:"https://www.openstreetmap.org/",facility:h};S.externalMode=true;S.view="explorer";await render();setTimeout(function(){var el=document.querySelector("#facilityConnection");if(el)el.scrollIntoView({behavior:"smooth",block:"center"})},80)}
async function bindFacilityButtons(){document.querySelectorAll("[data-facility]").forEach(function(b){b.onclick=function(){var h=S.hospitals.find(function(x){return String(x.id)===String(b.dataset.facility)});if(h)useFacility(h)}})}
async function edgeCopilot(){var base=(localStorage.getItem("care_ctrl_snapdragon_endpoint")||"http://127.0.0.1:18181/v1").replace(/\/$/,"");var q="Summarise the connected CARE & CTRL context for a healthcare operations user. Do not diagnose. If evidence is missing, say so.";var ctx=JSON.stringify({source:S.selectedSource,patients:S.patients.slice(0,40),generated_at:new Date().toISOString()});$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Connecting to Snapdragon Edge…</h3><p>Trying the configured GenieX OpenAI-compatible local endpoint.</p></div>";try{var mr=await fetch(base+"/models");if(!mr.ok)throw Error("Snapdragon Edge endpoint is not reachable");var models=await mr.json(),model=models.data?.[0]?.id;if(!model)throw Error("No GenieX model is available");var rr=await fetch(base+"/chat/completions",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer geniex"},body:JSON.stringify({model:model,messages:[{role:"system",content:"You are the CARE & CTRL local edge copilot. Use only supplied context. Never invent clinical facts. Do not diagnose."},{role:"user",content:q+"\nContext:\n"+ctx}],temperature:.2,max_tokens:300})});if(!rr.ok)throw Error("Snapdragon inference request failed");var out=await rr.json();var ans=out.choices?.[0]?.message?.content||"No edge response.";$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Snapdragon Edge Copilot</h3><p>"+esc(ans)+"</p><small>Local GenieX endpoint · model "+esc(model)+" · patient context stayed on the connected path.</small></div>"}catch(e){$("#copilotAnswer").innerHTML="<div class='ai-answer'><h3>Snapdragon Edge is not connected</h3><p>"+esc(e.message)+". CARE & CTRL is ready for a GenieX OpenAI-compatible endpoint; no fake edge result is shown.</p><small>Default endpoint: "+esc(base)+"</small></div>"}} 
