async function generateDashboardReport(){
 var btn=$("#generateReport"),status=$("#reportStatus"),d=S.dashboardData||{},f=S.dashboardFilter||{},idx=d.patient_index||[];
 if(btn)btn.disabled=true;if(status)status.textContent="Preparing report…";
 try{
   function reportVals(k){var v=f[k];return Array.isArray(v)?v:(v?[v]:[])}
   var names=idx.filter(function(p){var a=reportVals("patient");return !a.length||a.includes(String(p.id))}).map(function(p){return p.display_name}).slice(0,20);
   var reportCount=idx.filter(function(p){var a=reportVals("patient"),dx=reportVals("diagnosis"),md=reportVals("medication"),ag=reportVals("age"),sx=reportVals("sex"),sg=reportVals("signal");function ageFor(x){if(!x)return"Unknown";var dt=new Date(x),n=new Date(),v=n.getFullYear()-dt.getFullYear(),m=n.getMonth()-dt.getMonth();if(m<0||(m===0&&n.getDate()<dt.getDate()))v--;return v<18?"0–17":v<30?"18–29":v<45?"30–44":v<60?"45–59":v<75?"60–74":"75+"}return(!a.length||a.includes(String(p.id)))&&(!dx.length||dx.some(function(x){return p.diagnoses.includes(x)}))&&(!md.length||md.some(function(x){return p.medications.includes(x)}))&&(!ag.length||ag.includes(ageFor(p.date_of_birth)))&&(!sx.length||sx.includes(String(p.sex||"unknown").toLowerCase()))&&(!sg.length||sg.some(function(x){return p.signals.some(function(s){return String(s.type)===x})}))}).length;
   var lines=["CARE & CTRL","See earlier. Decide smarter.","","Workspace dashboard report","Generated: "+new Date().toLocaleString("en-IN"),"Source: "+(S.selectedSource?.name||S.selectedSource?.type||"Current workspace"),"","Filters:"];
   Object.keys(f).forEach(function(k){var a=reportVals(k);if(a.length)lines.push("• "+k+": "+a.join(", "))});
   if(!Object.keys(f).some(function(k){return reportVals(k).length}))lines.push("• None — full workspace view");
   lines.push("","Patients in view: "+reportCount);
   lines.push("","Patients: "+(names.join(", ")||"None"));
   lines.push("","Top diagnoses: "+((d.diagnoses||[]).slice(0,10).map(function(x){return x.diagnosis_name+" ("+x.count+")"}).join(", ")||"None"));
   lines.push("Top medications: "+((d.medications||[]).slice(0,10).map(function(x){return x.medication_name+" ("+x.count+")"}).join(", ")||"None"));
   lines.push("","Evidence note: Counts are based on records available to the selected workspace. Medication frequency is recorded medication rows, not inferred consumption.");
   S.generatedReportText=lines.join("\n");
   if(status)status.textContent="Report ready · review the generated file before using it externally.";
   var dl=$("#downloadReport");if(dl)dl.disabled=false;
 }catch(e){if(status)status.textContent="Report generation failed: "+e.message}finally{if(btn)btn.disabled=false}
}
function downloadDashboardReport(){
 var text=S.generatedReportText||"Generate the report first.";
 if(window.jspdf?.jsPDF){
   var pdf=new window.jspdf.jsPDF({unit:"pt",format:"a4"}),x=44,y=52,w=510;
   pdf.setFont("helvetica","bold");pdf.setFontSize(18);pdf.text("CARE & CTRL",x,y);y+=22;
   pdf.setFont("helvetica","normal");pdf.setFontSize(9);
   text.split("\n").forEach(function(line){if(y>790){pdf.addPage();y=52}var chunks=pdf.splitTextToSize(line,w);pdf.text(chunks,x,y);y+=12*chunks.length});
   pdf.save("care-ctrl-dashboard-report-"+new Date().toISOString().slice(0,10)+".pdf");
 }else{
   var blob=new Blob([text],{type:"text/plain;charset=utf-8"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="care-ctrl-dashboard-report.txt";a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},500);
 }
}
